#[path="../examples/m21_support/mod.rs"]mod support;
use support::*;
use spire_core::{combat::{CombatAction,CombatPublic,CharacterCombatView,FullPlayerView,Stance,StanceChoiceView},content::Character,run::*};
fn decision(actions:Vec<CombatAction>)->PublicDecision{PublicDecision{content_profile:None,room:None,reward_total:0,act:1,floor:0,player:PublicPlayer{relic_counters:vec![],character:Character::Watcher,hp:72,max_hp:72,gold:99,relics:vec![],potions:vec![None;3],keys:[false;3]},combat:Some(CombatPublic{mantra_gained:Some(0),stance_choice:None,played_powers:vec![],playing_cards:vec![],stasis:vec![],content_id:"fabricated public decision".into(),turn:1,player:FullPlayerView{hp:72,max_hp:72,block:0,energy:3,max_energy:3,powers:vec![]},enemies:vec![],character:CharacterCombatView{stance:Stance::Neutral,orbs:vec![],orb_dark_damage:vec![],focus:0},hand:vec![],draw_count:0,discard:vec![],exhaust:vec![],outcome:None,hp_before_healing:None,hp_after_cleanup:None,targets:vec![],selection:None,known_draw:vec![],encounter_facing:None,inventory:None,card_offer:None}),combat_progress:CombatProgress::default(),last_combat:None,objects:vec![],candidates:actions.into_iter().enumerate().map(|(i,a)|Candidate{id:ChoiceId(i as u64),action:GameAction::Combat(a),label:"fabricated public candidate",neow_offer:None,object:None}).collect(),offers:vec![],selection:None,terminal:None}}
#[test]fn m21_caller_death_always_ends_turn(){let d=decision(vec![CombatAction::UsePotion{slot:0,target:None},CombatAction::EndTurn]);assert_eq!(pick(&d,Scenario::Death).unwrap(),CombatAction::EndTurn);}
#[test]fn m21_caller_stance_chooses_calm_from_exact_public_options(){let mut d=decision(vec![CombatAction::ChooseStance{stance:Stance::Wrath},CombatAction::ChooseStance{stance:Stance::Calm}]);d.combat.as_mut().unwrap().stance_choice=Some(StanceChoiceView{options:vec![Stance::Wrath,Stance::Calm]});assert_eq!(pick(&d,Scenario::Potions).unwrap(),CombatAction::ChooseStance{stance:Stance::Calm});}
#[test]fn m21_caller_potions_ascending_slot_before_cards(){let d=decision(vec![CombatAction::PlayCard{instance:8,target:None},CombatAction::UsePotion{slot:2,target:None},CombatAction::UsePotion{slot:0,target:None}]);assert_eq!(pick(&d,Scenario::Creation).unwrap(),CombatAction::UsePotion{slot:0,target:None});}
#[test]fn m21_caller_starter_keeps_first_native_candidate(){let a=CombatAction::PlayCard{instance:8,target:None};assert_eq!(pick(&decision(vec![a.clone(),CombatAction::EndTurn]),Scenario::Starter).unwrap(),a);}
#[test]fn m21_caller_resource_matrix_is_fixed(){for s in SCENARIOS{let start=s.start().normalized().unwrap();if let M21WatcherCombatStart::Supplied(r)=start{assert_eq!((r.hp,r.max_hp,r.gold,r.potions.len()),(if s==Scenario::Death{1}else{72},72,99,3));assert_eq!(r.deck.len(),s.cards().len());assert!(r.deck.iter().all(|c|c.upgrades==0&&c.misc==0));}else{assert_eq!(s,Scenario::Starter);}}assert!(Scenario::parse("unknown").is_err());}
fn card(id:spire_core::content::CardId,instance:u64)->spire_core::combat::LiveCardView{spire_core::combat::LiveCardView{instance:spire_core::combat::CardInstanceId(instance),id,origin:spire_core::combat::CombatCardRef::Permanent(spire_core::combat::CardInstanceId(instance)),upgrades:0,misc:0,watcher:None,effective_cost:Some(1),values:None}}
#[test]fn m21_caller_card_priority_preserves_native_ties_and_targets(){use spire_core::content::CardId;let mut d=decision(vec![CombatAction::PlayCard{instance:8,target:None},CombatAction::PlayCard{instance:7,target:None},CombatAction::PlayCard{instance:6,target:None},CombatAction::EndTurn]);d.combat.as_mut().unwrap().hand=vec![card(CardId::Eruption,8),card(CardId::Vigilance,7),card(CardId::Vigilance,6)];assert_eq!(pick(&d,Scenario::Stance).unwrap(),CombatAction::PlayCard{instance:7,target:None});}
#[test]fn m21_caller_scry_takes_revealed_weave_then_zero_confirm(){use spire_core::{combat::{SelectionView,SelectionParent,SelectionOperation,SelectionSourceZone,SelectionDisposition,CardHandle},content::CardId};
 let mut d=decision(vec![CombatAction::SelectCard{instance:8},CombatAction::SelectCard{instance:7},CombatAction::ConfirmSelection]);
 d.combat.as_mut().unwrap().selection=Some(SelectionView{parent:SelectionParent::Card(CardHandle::parse("99").unwrap()),operation:SelectionOperation::Scry,candidates:vec![card(CardId::StrikePurple,8),card(CardId::Weave,7)],required:0,selected:vec![],disposition:SelectionDisposition::Discard,source_zone:SelectionSourceZone::Draw,minimum:0,maximum:2});
 assert_eq!(pick(&d,Scenario::Scry).unwrap(),CombatAction::SelectCard{instance:7});d.candidates.remove(1);d.combat.as_mut().unwrap().selection.as_mut().unwrap().selected.push(spire_core::combat::CardInstanceId(7));assert_eq!(pick(&d,Scenario::Scry).unwrap(),CombatAction::ConfirmSelection);
}
#[test]fn m21_caller_mandatory_pile_takes_first_legal_then_confirm(){use spire_core::{combat::{SelectionView,SelectionParent,SelectionOperation,SelectionSourceZone,SelectionDisposition,CardHandle},content::CardId};let mut d=decision(vec![CombatAction::SelectCard{instance:8},CombatAction::SelectCard{instance:7}]);d.combat.as_mut().unwrap().selection=Some(SelectionView{parent:SelectionParent::Card(CardHandle::parse("99").unwrap()),operation:SelectionOperation::MeditateReturn,candidates:vec![card(CardId::StrikePurple,8),card(CardId::Weave,7)],required:1,selected:vec![],disposition:SelectionDisposition::Hand,source_zone:SelectionSourceZone::Discard,minimum:1,maximum:1});assert_eq!(pick(&d,Scenario::Retain).unwrap(),CombatAction::SelectCard{instance:8});d.candidates=vec![Candidate{id:ChoiceId(0),action:GameAction::Combat(CombatAction::ConfirmSelection),label:"confirm",neow_offer:None,object:None}];assert_eq!(pick(&d,Scenario::Retain).unwrap(),CombatAction::ConfirmSelection);}
